INSERT INTO squad_entries VALUES(20,1,58,NULL,'W','OWNED','88210X4101720004100011000',7.030000000000000248,'r6','최근 6경기 평균 7.03 (첼시 25/26 실측)','w_winger','Versatile',0.936000000000000054,'transfer_targets 실측 이관(첼시 25/26) | 재산출 2026-08-06 (fc26-heatmap.html ROLE_VARIANTS 파싱, 역할 수 37 확인)','OWNED — 첼시에서 임대+조건부 의무매입(출전 수 연동, Ornstein 1티어). 실측 표본이 첼시 시절이라 에메리 체제 데이터가 아님. 로저스(→첼시 £117m) 이탈로 비어 있던 LW 슬롯을 메운다. | [2026-08-06 교정] obs#94(가르나초 insidefwd→winger 교체)가 WM 행에만 적용되고 W 행은 w_insidefwd/Attack + fit_sim 공란으로 남아 있었다. 파이썬으로 툴 decodeMap/placedMap/cmpCos를 재현해 재산출(회귀 게이트 하지무사 .821·은디아예 .825·가르나초 WM .804 전부 재현). W 슬롯 전 8개 조합에서 w_winger/Versatile 0.936이 최고이고 종전 값 w_insidefwd/Attack은 0.601로 **8개 중 최저**였다. x 버킷 15/28 모두 동일 변형을 선택해 값 불변.',26);
